{
  "description": "Searches for manga based on title, author, or keywords, with filtering options for NSFW content and the manga's origin (Japan, China, or Korea).",
  "required_parameters": [
    {
      "name": "text",
      "type": "String",
      "description": "The search term to query for manga title or content (e.g., 'Naruto')."
    }
  ],
  "optional_parameters": [
    {
      "name": "nsfw",
      "type": "String",
      "description": "Filter results by Not Safe For Work status. Use 'true' to get all manga (NSFW and non-NSFW), use 'false' to get only non-NSFW manga."
    },
    {
      "name": "type",
      "type": "String",
      "description": "The origin of the manga. Please choose from 'all', 'japan', 'china', or 'korea'.",
      "default": "all"
    }
  ]
}

