API_name: get_celestial_body_position
Description:
{
  "description": "Retrieves astronomical position data (e.g., azimuth, altitude) for a celestial body based on the observer's location (latitude, longitude, elevation) and a specified date and time range.",
  "required_parameters": [
    {
      "name": "body",
      "type": "String",
      "description": "The name of the celestial body (e.g., 'Sun', 'Moon', 'Mars', 'Jupiter') whose position is being requested."
    },
    {
      "name": "latitude",
      "type": "Number",
      "description": "The latitude component of the observer's location.",
      "default": "33.775867"
    },
    {
      "name": "longitude",
      "type": "Number",
      "description": "The longitude component of the observer's location.",
      "default": "-84.39733"
    },
    {
      "name": "from_date",
      "type": "String",
      "description": "The start date for the query in 'yyyy-mm-dd' format."
    },
    {
      "name": "to_date",
      "type": "String",
      "description": "The end date for the query in 'yyyy-mm-dd' format."
    }
  ],
  "optional_parameters": [
    {
      "name": "elevation",
      "type": "Number",
      "description": "The elevation (in meters) of the observer's location.",
      "default": "166"
    },
    {
      "name": "time",
      "type": "String",
      "description": "The time component to be used with the date (e.g., 'HH:MM:SS'). If not specified, a default time will be used."
    }
  ]
}

