Description:
{
  "description": "Search for restaurants within a geographic bounding box using GPS coordinates. Returns restaurant listings including name, cuisine, rating, and contact information, replicating TripAdvisor's restaurant search.",
  "required_parameters": [
    {
      "name": "bl_latitude",
      "type": "Number",
      "description": "Bottom-left (southwest) latitude of the bounding box search area.",
      "default": "11.847676"
    },
    {
      "name": "tr_latitude",
      "type": "Number",
      "description": "Top-right (northeast) latitude of the bounding box search area.",
      "default": "12.838442"
    },
    {
      "name": "bl_longitude",
      "type": "Number",
      "description": "Bottom-left (southwest) longitude of the bounding box search area.",
      "default": "108.587349"
    },
    {
      "name": "tr_longitude",
      "type": "Number",
      "description": "Top-right (northeast) longitude of the bounding box search area.",
      "default": "109.471078"
    }
  ],
  "optional_parameters": [
    {
      "name": "limit",
      "type": "Number",
      "description": "Maximum number of restaurant results to return per request.",
      "default": "30"
    },
    {
      "name": "currency",
      "type": "String",
      "description": "Currency code for price display (e.g., 'USD', 'EUR', 'TWD').",
      "default": "USD"
    },
    {
      "name": "offset",
      "type": "Number",
      "description": "Pagination offset for retrieving subsequent pages of results.",
      "default": "0"
    },
    {
      "name": "lang",
      "type": "String",
      "description": "Language/locale code for the response (e.g., 'en_US', 'zh_TW', 'ja_JP').",
      "default": "en_US"
    }
  ]
}

