API_name: calculate_route
Description:
{
  "description": "Provides detailed routing information based on multiple waypoints. Supports various route types, custom layout weights, language-specific directions, and voice instructions.",
  "required_parameters": [
    {
      "name": "points",
      "type": "String",
      "description": "Define multiple routing waypoints, consisting of latitude and longitude in the format '{lat},{lng}[|{lat},{lng} ...]'. At least 2 points are required."
    }
  ],
  "optional_parameters": [
    {
      "name": "routeType",
      "type": "String",
      "description": "The transport mode for routing. For example: 'bike'.",
      "default": "bike"
    },
    {
      "name": "weighting",
      "type": "String",
      "description": "Route optimization weighting strategy. Only available if the set routeType is 'bike'.",
      "default": "networks"
    },
    {
      "name": "language",
      "type": "String",
      "description": "Language for the given instructions. Must be a valid ISO 639-1 language code.",
      "default": "en"
    },
    {
      "name": "voice_instructions",
      "type": "String",
      "description": "Enables voice instructions formatted for text-to-speech engines.",
      "default": "false"
    },
    {
      "name": "finish_instruction",
      "type": "String",
      "description": "Adds a specific finish instruction at the end of the calculated route.",
      "default": "false"
    },
    {
      "name": "format",
      "type": "String",
      "description": "The output response format. Options usually include json, gpx, or kml.",
      "default": "json"
    },
    {
      "name": "filename",
      "type": "String",
      "description": "The file name assigned to the output. Only available if the set format is 'gpx' or 'kml'.",
      "default": ""
    }
  ]
}

