parsed.api_descriptions:
API_name: calculate_route
Description:
{
  "description": "Provides detailed routing information for a sequence of waypoints. Supports multiple transport modes (e.g., bike), route optimization strategies, multi-language turn-by-turn directions with optional voice instructions, and output in JSON, GPX, or KML formats.",
  "required_parameters": [
    {
      "name": "points",
      "type": "String",
      "description": "Define multiple routing waypoints as latitude/longitude pairs in the format '{lat},{lng}[|{lat},{lng}...]'. At least 2 points are required. Example: '47.5,8.5|47.6,8.6'."
    }
  ],
  "optional_parameters": [
    {
      "name": "routeType",
      "type": "String",
      "description": "The transport mode for routing. For example: 'bike'. Determines which routing engine and available options are used."
    },
    {
      "name": "weighting",
      "type": "String",
      "description": "Route optimization weighting strategy. Only available if routeType is 'bike'. Controls whether the route prefers road networks, shortest path, etc.",
      "default": "networks"
    },
    {
      "name": "language",
      "type": "String",
      "description": "Language for the turn-by-turn navigation instructions. Must be a valid ISO 639-1 language code (e.g., 'en', 'de', 'fr').",
      "default": "en"
    },
    {
      "name": "voice_instructions",
      "type": "String",
      "description": "Enables voice navigation instructions formatted for text-to-speech engines. Set to 'true' to include spoken prompts alongside written directions."
    },
    {
      "name": "finish_instruction",
      "type": "String",
      "description": "Adds a specific finish instruction at the end of the calculated route (e.g., 'You have arrived at your destination.')."
    },
    {
      "name": "format",
      "type": "String",
      "description": "The output response format. Options: 'json' (default), 'gpx' (GPS Exchange Format for device import), or 'kml' (Keyhole Markup Language for map applications).",
      "default": "json"
    },
    {
      "name": "filename",
      "type": "String",
      "description": "The file name assigned to the output. Only applicable when format is 'gpx' or 'kml'."
    }
  ]
}

