API_name: get_trades_futures
Description:
{
  "description": "Retrieves public futures trade records filtered by market venue, trading pair, and time ranges, with support for specific contract expiration types.",
  "required_parameters": [
    {
      "name": "market_venue",
      "type": "String",
      "description": "The name of the exchange or venue. Example: BINANCE.",
      "default": "BINANCE"
    },
    {
      "name": "base",
      "type": "String",
      "description": "The second listed currency of a currency pair. Example: USDT.",
      "default": "USDT"
    },
    {
      "name": "symbol",
      "type": "String",
      "description": "The first listed currency of a currency pair. Example: BTC.",
      "default": "BTC"
    }
  ],
  "optional_parameters": [
    {
      "name": "sort",
      "type": "String",
      "description": "The ordering of results. Available options: asc (earliest to latest), desc (latest to earliest).",
      "default": "asc"
    },
    {
      "name": "start",
      "type": "String",
      "description": "Start of the requested time period. Format: YYYY-MM-DDTHH:MM:SS UTC.",
      "default": "2023-05-05T10:05:00"
    },
    {
      "name": "end",
      "type": "String",
      "description": "End of the requested time period. Format: YYYY-MM-DDTHH:MM:SS UTC.",
      "default": "2023-05-06T10:05:00"
    },
    {
      "name": "limit",
      "type": "Number",
      "description": "Maximum number of records to return. Maximum value is 10000.",
      "default": "100"
    },
    {
      "name": "expiration",
      "type": "String",
      "description": "The lifespan of a futures contract. Available options: perpetual, weekly, quarterly, monthly.",
      "default": "perpetual"
    },
    {
      "name": "delivery_date",
      "type": "String",
      "description": "The last day when a future contract is valid. Format: YYYY-MM-DD.",
      "default": ""
    }
  ]
}

