Description:
{
  "description": "Retrieves real-time flight data within a specified geographic bounding box defined by bottom-left and top-right coordinates, with options to filter by aircraft characteristics, speed, and airline.",
  "required_parameters": [
    {
      "name": "bl_lat",
      "type": "Number",
      "description": "The bottom left latitude of the bounding box.",
      "default": "13.607884"
    },
    {
      "name": "bl_lng",
      "type": "Number",
      "description": "The bottom left longitude of the bounding box.",
      "default": "100.641975"
    },
    {
      "name": "tr_lat",
      "type": "Number",
      "description": "The top right latitude of the bounding box.",
      "default": "13.771029"
    },
    {
      "name": "tr_lng",
      "type": "Number",
      "description": "The top right longitude of the bounding box.",
      "default": "100.861566"
    }
  ],
  "optional_parameters": [
    {
      "name": "limit",
      "type": "Number",
      "description": "The number of flights per response. Cannot exceed 300.",
      "default": "300"
    },
    {
      "name": "speed",
      "type": "String",
      "description": "Filter flights by ground speed. The format must be 'min,max'. For example: '0,460'."
    },
    {
      "name": "altitude",
      "type": "String",
      "description": "Filter flights by altitude. The format must be 'min,max'. For example: '0,48000'."
    },
    {
      "name": "airline",
      "type": "String",
      "description": "Filter flights by airline. Enter the 3-letter ICAO airline code (e.g., 'THA' for Thai Airways)."
    },
    {
      "name": "type",
      "type": "String",
      "description": "Filter flights by aircraft type. Enter the ICAO or IATA aircraft type code (e.g., 'A359' or '77W')."
    },
    {
      "name": "airport",
      "type": "String",
      "description": "Filter flights by airport. Enter the 3-letter IATA airport code (e.g., 'BKK' or 'TPE')."
    },
    {
      "name": "reg",
      "type": "String",
      "description": "Filter flights by aircraft registration number. For example: 'D-AIHV'."
    }
  ]
}

