API_name: list_of_deals
Description:
{
  "description": "Get a paged list of game deals matching any number of optional filtering criteria, including price ranges, ratings, stores, and titles.",
  "required_parameters": [],
  "optional_parameters": [
    {
      "name": "lowerPrice",
      "type": "Number",
      "description": "Only returns deals with a price greater than this value.",
      "default": "0"
    },
    {
      "name": "upperPrice",
      "type": "Number",
      "description": "Only returns deals with a price less than or equal to this value. A value of 50 acts as no limit.",
      "default": "50"
    },
    {
      "name": "title",
      "type": "String",
      "description": "Looks for the string contained anywhere in the game name.",
      "default": "batman"
    },
    {
      "name": "exact",
      "type": "Boolean",
      "description": "Flag to allow only exact string match for the title parameter. 0=false, 1=true.",
      "default": "0"
    },
    {
      "name": "steamAppID",
      "type": "String",
      "description": "Look for deals on specific games. Comma separated list of Steam App IDs.",
      "default": ""
    },
    {
      "name": "storeID",
      "type": "String",
      "description": "Comma separated list of store IDs to filter on. Examples: 1: Steam, 2: GamersGate, 3: GreenManGaming, 7: GoG, 25: Epic Games Store.",
      "default": "1,2,3"
    },
    {
      "name": "steamRating",
      "type": "Number",
      "description": "Minimum Steam reviews rating score for a game.",
      "default": "0"
    },
    {
      "name": "metacritic",
      "type": "Number",
      "description": "Minimum Metacritic rating score for a game.",
      "default": "0"
    },
    {
      "name": "onSale",
      "type": "Boolean",
      "description": "Flag to include only games that are currently on sale. 0=false, 1=true.",
      "default": "0"
    },
    {
      "name": "AAA",
      "type": "Boolean",
      "description": "Flag to include only deals with a retail price greater than 29 dollars. 0=false, 1=true.",
      "default": "0"
    },
    {
      "name": "steamworks",
      "type": "Boolean",
      "description": "Flag to include only deals that redeem on Steam. 0=false, 1=true.",
      "default": "0"
    },
    {
      "name": "sortBy",
      "type": "String",
      "description": "Criteria to sort the list by. Available options: Deal Rating, Title, Savings, Price, Metacritic, Reviews, Release, Store, recent.",
      "default": "Deal Rating"
    },
    {
      "name": "desc",
      "type": "Boolean",
      "description": "Determines sort direction. 0=ascending, 1=descending.",
      "default": "0"
    },
    {
      "name": "output",
      "type": "String",
      "description": "Option to output deals in RSS format. Overrides page number and size to 0 and 100 if set.",
      "default": "json"
    },
    {
      "name": "pageNumber",
      "type": "Number",
      "description": "The requested page number, 0 indexed.",
      "default": "0"
    },
    {
      "name": "pageSize",
      "type": "Number",
      "description": "The size of pages returned. Maximum value is 60.",
      "default": "60"
    }
  ]
}

