API_name: search_businesses
Description:
{
  "description": "Searches for businesses and locations on Google Maps using keywords, supporting geographical biasing, category filtering, and contact data enrichment.",
  "required_parameters": [
    {
      "name": "query",
      "type": "String",
      "description": "Search query or keyword. Examples: Plumbers near New-York, USA or Bars in 94102, USA."
    }
  ],
  "optional_parameters": [
    {
      "name": "limit",
      "type": "Number",
      "description": "Maximum number of businesses to return. Allowed values range from 1 to 500.",
      "default": "20"
    },
    {
      "name": "lat",
      "type": "Number",
      "description": "Latitude of the coordinates point to bias results towards a specific location.",
      "default": "37.359428"
    },
    {
      "name": "lng",
      "type": "Number",
      "description": "Longitude of the coordinates point to bias results towards a specific location.",
      "default": "-121.925337"
    },
    {
      "name": "zoom",
      "type": "String",
      "description": "Zoom level on which to make the search, determining the viewport along with lat and lng.",
      "default": "13"
    },
    {
      "name": "language",
      "type": "String",
      "description": "Set the language of the results using standard ISO 639-1 language codes.",
      "default": "en"
    },
    {
      "name": "region",
      "type": "String",
      "description": "Query Google Maps from a particular region or country using ISO 3166 Alpha-2 codes.",
      "default": "us"
    },
    {
      "name": "subtypes",
      "type": "String",
      "description": "Find businesses with specific subtypes, specified as a comma-separated list of categories. Examples: Plumber,Carpenter,Electrician.",
      "default": ""
    },
    {
      "name": "verified",
      "type": "Boolean",
      "description": "Filter to only return verified businesses.",
      "default": "false"
    },
    {
      "name": "business_status",
      "type": "String",
      "description": "Filter by business operational status. Comma-separated list of values: OPEN, CLOSED_TEMPORARILY, CLOSED.",
      "default": ""
    },
    {
      "name": "extract_emails_and_contacts",
      "type": "Boolean",
      "description": "Extract emails, social profiles, and phones by scraping the business website. Note that enabling this may incur additional API credits.",
      "default": "false"
    },
    {
      "name": "fields",
      "type": "String",
      "description": "A comma-separated list of business fields to include in the response for field projection. Example: business_id,type,phone_number,full_address.",
      "default": ""
    }
  ]
}

