API_name: search_amazon_products
Description:
{
  "description": "Search for Amazon products using keywords and filters. Returns real-time product listings including titles, prices, ratings, and availability from Amazon's marketplace.",
  "required_parameters": [
    {
      "name": "query",
      "type": "String",
      "description": "The search keyword or phrase to look up on Amazon (e.g., 'wireless headphones', 'laptop stand').",
      "default": "wireless headphones"
    }
  ],
  "optional_parameters": [
    {
      "name": "page",
      "type": "Number",
      "description": "Page number for pagination of results. Starts at 1.",
      "default": "1"
    },
    {
      "name": "country",
      "type": "String",
      "description": "Amazon marketplace country code (e.g., 'US', 'GB', 'CA', 'DE', 'JP'). Default is 'US'.",
      "default": "US"
    },
    {
      "name": "sort_by",
      "type": "String",
      "description": "Sort order for results. Options: 'RELEVANCE', 'LOWEST_PRICE', 'HIGHEST_PRICE', 'REVIEWS', 'NEWEST'. Default is 'RELEVANCE'.",
      "default": "RELEVANCE"
    },
    {
      "name": "product_condition",
      "type": "String",
      "description": "Filter by product condition. Options: 'ALL', 'NEW', 'USED', 'RENEWED'. Default is 'ALL'.",
      "default": "ALL"
    },
    {
      "name": "min_price",
      "type": "Number",
      "description": "Minimum price filter in the marketplace's local currency."
    },
    {
      "name": "max_price",
      "type": "Number",
      "description": "Maximum price filter in the marketplace's local currency."
    }
  ]
}

